-- Forward security hardening applied to Supabase on 2026-09-08.
BEGIN;
CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path = '' AS $function$ declare claims jsonb; v_role text; v_owner boolean; begin select lower(r.code) into v_role from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.user_id=(event->>''user_id'')::uuid order by r.priority desc limit 1; v_owner := (v_role=''dragon''); claims:=event->''claims''; claims:=jsonb_set(claims,''{user_role}'',pg_catalog.to_jsonb(coalesce(v_role,''user''))); claims:=jsonb_set(claims,''{platform_owner}'',pg_catalog.to_jsonb(v_owner)); return jsonb_set(event,''{claims}'',claims); end; $function$;
REVOKE ALL ON TABLE public.user_vip_entitlements FROM anon; REVOKE ALL ON TABLE public.platform_owners FROM anon; REVOKE ALL ON TABLE public.subscription_tier_service_rules FROM anon; REVOKE ALL ON TABLE public.chat_visual_size_authority FROM anon; REVOKE ALL ON TABLE public.chat_visual_size_overrides FROM anon; REVOKE ALL ON TABLE public.chat_visual_size_settings FROM anon;
REVOKE ALL ON TABLE public.platform_login_announcements FROM anon; REVOKE ALL ON TABLE public.platform_login_announcement_views FROM anon; GRANT SELECT ON TABLE public.platform_login_announcements TO authenticated; GRANT SELECT ON TABLE public.platform_login_announcement_views TO authenticated;
COMMIT;
